namespace Ordering;

/// <summary>Imports orders from a batch of delimited rows.</summary>
public sealed class OrderImporter
{
    private readonly OrderRepository _repository;

    public OrderImporter(OrderRepository repository) => _repository = repository;

    public IReadOnlyList<Order> ImportBatch(IEnumerable<string> rows)
    {
        var imported = new List<Order>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var row in rows)
        {
            if (!TryParseOrder(row, seen, out var order))
                continue;

            _repository.Add(order);
            imported.Add(order);
        }

        return imported;
    }

    private static bool TryParseOrder(string row, HashSet<string> seen, out Order order)
    {
        order = default!;
        if (string.IsNullOrWhiteSpace(row))
            return false;

        var parts = row.Split(',');
        if (parts.Length < 4)
            return false;

        var recordType = parts[0].Trim();
        var reference = parts[1].Trim();
        if (reference.Length == 0 || !seen.Add(reference))
            return false;

        if (!TryGetChannel(recordType, out var channel))
            return false;

        order = new Order { Reference = reference, Channel = channel };
        AddLines(order, parts);
        return order.Lines.Count > 0;
    }

    private static bool TryGetChannel(string recordType, out OrderChannel channel)
    {
        switch (recordType)
        {
            case "H":
            case "ORDER":
                channel = OrderChannel.Web;
                return true;
            case "M":
                channel = OrderChannel.Marketplace;
                return true;
            default:
                channel = default;
                return false;
        }
    }

    private static void AddLines(Order order, string[] parts)
    {
        for (var i = 2; i + 1 < parts.Length; i += 2)
        {
            if (TryCreateLine(parts[i], parts[i + 1], out var line))
                order.Lines.Add(line);
        }
    }

    private static bool TryCreateLine(string skuPart, string quantityPart, out OrderLine line)
    {
        line = default!;
        var sku = skuPart.Trim();
        if (sku.Length == 0)
            return false;

        if (!int.TryParse(quantityPart, out var quantity) || quantity <= 0)
            return false;

        line = new OrderLine
        {
            Sku = sku,
            Quantity = quantity,
            UnitPrice = GetUnitPrice(sku, quantity)
        };
        return true;
    }

    private static decimal GetUnitPrice(string sku, int quantity)
    {
        if (sku.StartsWith("PRM", StringComparison.Ordinal) && quantity > 10)
            return 9.99m;
        if (sku.StartsWith("STD", StringComparison.Ordinal))
            return 4.99m;
        return 0m;
    }
}
